#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
unordered_map<long long,int>cnt,first;unordered_map<long long,int>last;
int deg=0;
for(int i=0;i<n;++i){scanf("%lld",&a[i]);
if(!first.count(a[i]))first[a[i]]=i;
last[a[i]]=i;deg=max(deg,++cnt[a[i]]);}
int best=n;
for(auto&kv:cnt)if(kv.second==deg)best=min(best,last[kv.first]-first[kv.first]+1);
printf("%d\n",best);return 0;}

